  cases: [
    { id: "ch05-case-bloating", title: "Mu\u1ED1n b\u1ECF c\xF9ng l\xFAc nhi\u1EC1u nh\xF3m th\u1EF1c ph\u1EA9m", context: "Sau m\u1ED9t l\u1EA7n \u0111\u1EA7y b\u1EE5ng, Ph\xFAc \u0111\u1ECBnh b\u1ECF s\u1EEFa, l\xFAa m\xEC v\xE0 nhi\u1EC1u lo\u1EA1i kh\xE1c trong m\u1ED9t th\xE1ng \u0111\u1EC3 t\xECm th\u1EE7 ph\u1EA1m.", question: "V\xEC sao b\xE0i h\u1ECDc kh\xF4ng y\xEAu c\u1EA7u l\xE0m th\u1EED nh\u01B0 v\u1EADy?", reasoning: ["M\u1ED9t l\u1EA7n tri\u1EC7u ch\u1EE9ng ch\u01B0a x\xE1c nh\u1EADn nguy\xEAn nh\xE2n.", "Thay nhi\u1EC1u y\u1EBFu t\u1ED1 c\xF9ng l\xFAc kh\xF4ng gi\xFAp t\xE1ch \u0111\xF3ng g\xF3p c\u1EE7a t\u1EEBng y\u1EBFu t\u1ED1.", "Ch\u1EBF \u0111\u1ED9 lo\u1EA1i tr\u1EEB \u0111i\u1EC1u tr\u1ECB n\u1EB1m ngo\xE0i b\xE0i t\u1EADp v\xE0 c\u1EA7n \u0111\xE1nh gi\xE1 ph\xF9 h\u1EE3p."], safeNextStep: "Ghi d\u1EEF ki\u1EC7n s\u1EB5n c\xF3 v\xE0 c\xE2u h\u1ECFi cho nh\xE2n vi\xEAn y t\u1EBF n\u1EBFu c\u1EA7n; l\xE0m b\xE0i b\u1EB1ng ca gi\u1EA3 \u0111\u1ECBnh, kh\xF4ng t\u1EF1 g\xE2y tri\u1EC7u ch\u1EE9ng.", commonError: "Coi lo\u1EA1i c\xE0ng nhi\u1EC1u th\u1EF1c ph\u1EA9m c\xE0ng l\xE0 c\xE1ch ki\u1EC3m ch\u1EE9ng khoa h\u1ECDc." },
    { id: "ch05-case-celiac", title: "\u0110\xE3 t\u1EF1 ki\xEAng tr\u01B0\u1EDBc ng\xE0y kh\xE1m", context: "Vy nghi celiac v\xE0 \u0111\xE3 b\u1ECF gluten tr\u01B0\u1EDBc khi h\u1EB9n b\xE1c s\u0129. B\u1EA1n khuy\xEAn t\u1EF1 \u0103n th\u1EADt nhi\u1EC1u l\u1EA1i \u0111\u1EC3 x\xE9t nghi\u1EC7m cho r\xF5.", question: "C\xE1ch chuy\u1EC3n th\xF4ng tin n\xE0o an to\xE0n h\u01A1n?", reasoning: ["Ch\u1EBF \u0111\u1ED9 tr\u01B0\u1EDBc \u0111\xE1nh gi\xE1 c\xF3 th\u1EC3 \u1EA3nh h\u01B0\u1EDFng k\u1EBFt qu\u1EA3.", "Kh\xF4ng t\u1EF1 ch\u1ECDn c\xE1ch th\u1EED l\u1EA1i ho\u1EB7c l\u01B0\u1EE3ng gluten.", "B\xE1c s\u0129 c\u1EA7n bi\u1EBFt vi\u1EC7c \u0111\xE3 ki\xEAng v\xE0 th\u1EDDi \u0111i\u1EC3m thay \u0111\u1ED5i."], safeNextStep: "B\xE1o trung th\u1EF1c vi\u1EC7c \u0111\xE3 ki\xEAng v\xE0 h\u1ECFi b\xE1c s\u0129 chu\u1EA9n b\u1ECB th\u1EBF n\xE0o; kh\xF4ng t\u1EF1 \u0103n l\u1EA1i \u0111\u1EC3 ph\u1EE5c v\u1EE5 b\xE0i h\u1ECDc ho\u1EB7c x\xE9t nghi\u1EC7m.", commonError: "Bi\u1EBFn th\xF4ng tin \u201Cc\xF3 th\u1EC3 \u1EA3nh h\u01B0\u1EDFng x\xE9t nghi\u1EC7m\u201D th\xE0nh ch\u1EC9 \u0111\u1ECBnh t\u1EF1 th\u1EED l\u1EA1i th\u1EF1c ph\u1EA9m." },
    { id: "ch05-case-urgent", title: "S\u01B0ng h\u1ECDng v\xE0 kh\xF3 th\u1EDF sau \u0103n", context: "Trong ca gi\u1EA3 \u0111\u1ECBnh, ng\u01B0\u1EDDi t\u1EA1i bu\u1ED5i t\u1EADp \u0111\u1ED9t ng\u1ED9t s\u01B0ng h\u1ECDng v\xE0 kh\xF3 th\u1EDF sau \u0103n.", question: "C\xF3 n\xEAn \u0111i\u1EC1n nh\u1EADt k\xFD \u0111\u1EC3 coach x\xE1c nh\u1EADn tr\u01B0\u1EDBc kh\xF4ng?", reasoning: ["\u0110\xE2y l\xE0 bi\u1EC3u hi\u1EC7n c\u1EA7n tr\u1EE3 gi\xFAp kh\u1EA9n c\u1EA5p, kh\xF4ng ch\u1EDD x\xE1c \u0111\u1ECBnh nguy\xEAn nh\xE2n qua app.", "Nh\u1EADt k\xFD v\xE0 ti\u1EBFn \u0111\u1ED9 kh\xF3a h\u1ECDc kh\xF4ng \u0111\u01B0\u1EE3c l\xE0m ch\u1EADm h\u1ED7 tr\u1EE3.", "L\xE0m theo h\u01B0\u1EDBng d\u1EABn c\u1EA5p c\u1EE9u v\xE0 k\u1EBF ho\u1EA1ch y t\u1EBF c\xE1 nh\xE2n n\u1EBFu c\xF3."], safeNextStep: "D\u1EEBng ho\u1EA1t \u0111\u1ED9ng, g\u1ECDi tr\u1EE3 gi\xFAp kh\u1EA9n c\u1EA5p t\u1EA1i \u0111\u1ECBa ph\u01B0\u01A1ng; kh\xF4ng ch\u1EDD coach duy\u1EC7t ho\u1EB7c t\u1EF1 cho \u0103n th\u1EED \u0111\u1EC3 x\xE1c minh.", commonError: "C\u1ED1 thu \u0111\u1EE7 d\u1EEF ki\u1EC7n ho\u1EB7c ch\u1EDD ph\u1EA3n h\u1ED3i tr\u1EF1c tuy\u1EBFn tr\u01B0\u1EDBc khi g\u1ECDi tr\u1EE3 gi\xFAp." }
  ],
