    {
      id: "ch10-bia-example",
      title: "\u0110\xFAng ph\xE9p nh\xE2n nh\u01B0ng ch\u01B0a ch\u1EE9ng minh gi\u1EA3m m\u1EE1 th\u1EADt",
      objectiveIds: ["ch10-quality", "ch10-decision"],
      prompt: "Hai l\u1EA7n hi\u1EC3n th\u1ECB gi\u1EA3 \u0111\u1ECBnh c\u1EE7a m\u1ED9t c\xE2n: 60 kg v\u1EDBi 22% m\u1EE1 v\xE0 59,5 kg v\u1EDBi 20% m\u1EE1. T\xEDnh gi\xE1 tr\u1ECB suy ra, r\u1ED3i gi\u1EEF gi\u1EDBi h\u1EA1n.",
      given: ["L\u1EA7n 1: 60 \xD7 22%.", "L\u1EA7n 2: 59,5 \xD7 20%.", "\u0110\xE2y l\xE0 s\u1ED1 do thi\u1EBFt b\u1ECB \u01B0\u1EDBc t\xEDnh; ch\u01B0a c\xF3 d\u1EEF li\u1EC7u \u0111\u1ED9 \u0111\xFAng v\xE0 kh\u1EA3 n\u0103ng ph\xE1t hi\u1EC7n thay \u0111\u1ED5i."],
      steps: ["L\u1EA7n 1 suy ra 60 \xD7 0,22 = 13,2 kg theo \u01B0\u1EDBc t\xEDnh.", "L\u1EA7n 2 suy ra 59,5 \xD7 0,20 = 11,9 kg theo \u01B0\u1EDBc t\xEDnh.", "Ch\xEAnh l\u1EC7ch gi\xE1 tr\u1ECB suy ra l\xE0 11,9 \u2212 13,2 = \u22121,3 kg.", "Kh\xF4ng \u0111\u1ED5i c\xE1ch g\u1ECDi th\xE0nh \u201Cch\u1EAFc ch\u1EAFn gi\u1EA3m 1,3 kg m\u1EE1\u201D; ki\u1EC3m tra \u0111i\u1EC1u ki\u1EC7n v\xE0 gi\u1EDBi h\u1EA1n thi\u1EBFt b\u1ECB tr\u01B0\u1EDBc di\u1EC5n gi\u1EA3i."],
      answer: "Hai gi\xE1 tr\u1ECB \u01B0\u1EDBc t\xEDnh l\xE0 13,2 v\xE0 11,9 kg, ch\xEAnh \u22121,3 kg theo s\u1ED1 hi\u1EC3n th\u1ECB; ch\u01B0a x\xE1c nh\u1EADn m\xF4 m\u1EE1 th\u1EADt.",
      limitation: "Kh\xF4ng suy t\u0103ng c\u01A1, t\u1ED1c \u0111\u1ED9 sinh h\u1ECDc ho\u1EB7c hi\u1EC7u qu\u1EA3 k\u1EBF ho\u1EA1ch ch\u1EC9 t\u1EEB ph\xE9p nh\xE2n ph\u1EA7n tr\u0103m c\u1EE7a thi\u1EBFt b\u1ECB."
    },
    {
      id: "ch10-decision-example",
      title: "K\u1EBFt qu\u1EA3 t\u1ED5 ch\u1EE9c t\u1ED1t h\u01A1n, tr\u1EA3i nghi\u1EC7m ghi ch\xE9p t\u1EC7 h\u01A1n",
      objectiveIds: ["ch10-decision", "ch10-portfolio"],
      prompt: "Ca gi\u1EA3 \u0111\u1ECBnh chu\u1EA9n b\u1ECB b\u1EEFa th\u01B0\u1EDDng xuy\xEAn h\u01A1n nh\u01B0ng th\u1EA5y b\u1EA3ng ghi qu\xE1 nhi\u1EC1u m\u1EE5c v\xE0 b\u1EAFt \u0111\u1EA7u lo ph\u1EA3i ho\xE0n h\u1EA3o.",
      given: ["Minh ch\u1EE9ng ch\u01B0\u01A1ng 9 cho th\u1EA5y \u0111\xE3 c\xF3 ph\u01B0\u01A1ng \xE1n d\u1EF1 ph\xF2ng.", "B\u1EA3ng ch\u01B0\u01A1ng 10 thu 12 m\u1EE5c nh\u01B0ng nhi\u1EC1u m\u1EE5c kh\xF4ng g\u1EAFn quy\u1EBFt \u0111\u1ECBnh.", "B\xE0i ch\u01B0\u01A1ng 6 m\u1EDBi l\xE0 nh\xE1p, ch\u01B0a n\u1ED9p."],
      steps: ["Gi\u1EEF th\xF4ng tin v\u1EC1 c\u1EA3i thi\u1EC7n vi\u1EC7c t\u1ED5 ch\u1EE9c nh\u01B0ng kh\xF4ng b\u1ECF qua tr\u1EA3i nghi\u1EC7m kh\xF3 ch\u1ECBu.", "B\u1ECF m\u1EE5c kh\xF4ng ph\u1EE5c v\u1EE5 c\xE2u h\u1ECFi, thi\u1EBFt k\u1EBF b\u1EA3ng nh\u1EB9 h\u01A1n; t\xECm h\u1ED7 tr\u1EE3 n\u1EBFu vi\u1EC7c theo d\xF5i g\xE2y h\u1EA1i.", "Ghi gi\u1EDBi h\u1EA1n: ch\u01B0a k\u1EBFt lu\u1EADn v\u1EC1 s\u1EE9c kh\u1ECFe ho\u1EB7c nhu c\u1EA7u n\u0103ng l\u01B0\u1EE3ng.", "Portfolio v\u1EABn thi\u1EBFu minh ch\u1EE9ng ch\u01B0\u01A1ng 6 \u0111\xE3 n\u1ED9p; x\u1EED l\xFD b\xE0i \u0111\xF3 ri\xEAng, kh\xF4ng t\u1EF1 \u0111\xE1nh d\u1EA5u \u0111\u1EE7 n\u0103m."],
      answer: "\u0110\u01A1n gi\u1EA3n h\xF3a c\xE1ch theo d\xF5i v\xE0 l\xE0m r\xF5 an to\xE0n; portfolio ch\u01B0a \u0111\u1EE7 ch\u1EC9 v\xEC b\u1ED1n b\xE0i kh\xE1c \u0111\xE3 c\xF3.",
      limitation: "Kh\xF4ng ch\u1EA9n \u0111o\xE1n r\u1ED1i lo\u1EA1n \u0103n u\u1ED1ng t\u1EEB m\u1ED9t c\xE2u k\u1EC3 v\xE0 kh\xF4ng d\xF9ng \u0111i\u1EC3m t\u1EF1 soi \u0111\u1EC3 thay ph\u1EA3n h\u1ED3i chuy\xEAn m\xF4n."
    }
