  cases: [
    { id: "ch11-case-rush", title: "B\u1EEFa l\u1EDBn ngay tr\u01B0\u1EDBc t\u1EADp", context: "An \u0103n v\u1ED9i m\u1ED9t b\u1EEFa l\u1EDBn s\xE1t gi\u1EDD v\xE0 kh\xF3 ch\u1ECBu, r\u1ED3i mu\u1ED1n b\u1ECF m\u1ECDi b\u1EEFa tr\u01B0\u1EDBc t\u1EADp.", question: "C\xF3 l\u1EF1a ch\u1ECDn n\xE0o gi\u1EEFa \xE9p \u0103n v\xE0 nh\u1ECBn m\u1EB7c \u0111\u1ECBnh?", reasoning: ["M\u1ED9t l\u1EA7n kh\xF3 ch\u1ECBu ch\u01B0a ch\u1EC9 ra m\u1ED9t th\xE0nh ph\u1EA7n duy nh\u1EA5t.", "C\xF3 th\u1EC3 r\xE0 th\u1EDDi \u0111i\u1EC3m, l\u01B0\u1EE3ng, t\u1ED1c \u0111\u1ED9 \u0103n v\xE0 m\xF3n quen.", "Tri\u1EC7u ch\u1EE9ng l\u1EB7p l\u1EA1i ho\u1EB7c \u0111\xE1ng lo c\u1EA7n h\u1ECFi chuy\xEAn m\xF4n."], safeNextStep: "Vi\u1EBFt m\u1ED9t ph\u01B0\u01A1ng \xE1n h\u1EADu c\u1EA7n v\u1EEBa s\u1EE9c cho bu\u1ED5i th\u01B0\u1EDDng v\xE0 gi\u1EDBi h\u1EA1n th\u1EED; kh\xF4ng t\u1EF1 lo\u1EA1i nhi\u1EC1u nh\xF3m th\u1EF1c ph\u1EA9m.", commonError: "T\u1EEB m\u1ED9t tr\u1EA3i nghi\u1EC7m suy ra ph\u1EA3i nh\u1ECBn ho\u1EB7c c\u1EA5m m\u1ED9t ch\u1EA5t cho m\u1ECDi bu\u1ED5i." },
    { id: "ch11-case-fluid", title: "U\u1ED1ng theo b\u1EA1n r\u1ED3i th\u1EA5y kh\xF3 ch\u1ECBu", context: "M\u1ED9t ng\u01B0\u1EDDi c\u1ED1 u\u1ED1ng theo \u0111\u1ECBnh m\u1EE9c c\u1EE7a b\u1EA1n, t\u0103ng c\xE2n trong bu\u1ED5i v\xE0 c\xF3 \u0111au \u0111\u1EA7u, bu\u1ED3n n\xF4n.", question: "C\xF3 n\xEAn t\u1EF1 u\u1ED1ng th\xEAm n\u01B0\u1EDBc ho\u1EB7c mu\u1ED1i \u0111\u1EC3 s\u1EEDa kh\xF4ng?", reasoning: ["C\xE1c tri\u1EC7u ch\u1EE9ng c\xF3 nhi\u1EC1u nguy\xEAn nh\xE2n.", "U\u1ED1ng qu\xE1 m\u1EE9c c\u0169ng c\xF3 th\u1EC3 nguy hi\u1EC3m.", "Kh\xF4ng d\xF9ng c\xE2n ho\u1EB7c b\xE0i to\xE1n \u0111\u1EC3 t\u1EF1 x\u1EED tr\xED tri\u1EC7u ch\u1EE9ng."], safeNextStep: "D\u1EEBng t\u1EADp, t\xECm \u0111\xE1nh gi\xE1 y t\u1EBF k\u1ECBp th\u1EDDi; n\u1EBFu l\xFA l\u1EABn, ng\u1EA5t ho\u1EB7c di\u1EC5n bi\u1EBFn n\u1EB7ng, g\u1ECDi tr\u1EE3 gi\xFAp kh\u1EA9n c\u1EA5p.", commonError: "M\u1EB7c \u0111\u1ECBnh m\u1ECDi kh\xF3 ch\u1ECBu khi t\u1EADp l\xE0 thi\u1EBFu n\u01B0\u1EDBc v\xE0 ti\u1EBFp t\u1EE5c \xE9p u\u1ED1ng." },
    { id: "ch11-case-shake", title: "Qu\xEAn shake sau t\u1EADp", context: "B\xECnh c\xF3 b\u1EEFa t\u1ED1i ph\xF9 h\u1EE3p sau t\u1EADp nh\u01B0ng ngh\u0129 qu\xEAn shake l\xE0m c\u1EA3 bu\u1ED5i v\xF4 \xEDch.", question: "C\u1EA7n \u0111\u1ECDc l\u1EA1i vai tr\xF2 n\xE0o c\u1EE7a b\u1EEFa sau?", reasoning: ["S\u1EA3n ph\u1EA9m kh\xF4ng \u0111\u1ED3ng ngh\u0129a nhu c\u1EA7u.", "B\u1EEFa th\u1EADt c\xF3 th\u1EC3 cung c\u1EA5p c\xE1c ch\u1EA5t c\u1EA7n t\u1ED5 ch\u1EE9c.", "C\xF2n ph\u1EA3i xem t\u1ED5ng ng\xE0y v\xE0 khi n\xE0o t\u1EADp l\u1EA1i."], safeNextStep: "Ki\u1EC3m tra b\u1EEFa t\u1ED1i c\xF9ng l\u1ECBch ph\u1EE5c h\u1ED3i, kh\xF4ng mua b\xF9 ho\u1EB7c t\u1EADp th\xEAm \u0111\u1EC3 s\u1EEDa m\u1ED9t nghi th\u1EE9c b\u1ECB thi\u1EBFu.", commonError: "\u0110\xE1nh gi\xE1 bu\u1ED5i t\u1EADp ch\u1EC9 b\u1EB1ng vi\u1EC7c c\xF3 u\u1ED1ng m\u1ED9t s\u1EA3n ph\u1EA9m \u0111\xFAng ph\xFAt hay kh\xF4ng." }
  ],
