    { id: "ch14-case-kidney", title: "C\xF9ng c\xE2n n\u1EB7ng, kh\xE1c y\xEAu c\u1EA7u ch\u0103m s\xF3c", context: "Ng\u01B0\u1EDDi c\xF3 b\u1EC7nh th\u1EADn mu\u1ED1n l\u1EA5y ngay k\u1EBFt qu\u1EA3 protein c\u1EE7a nh\xE2n v\u1EADt 70 kg trong b\xE0i.", question: "Ph\xE9p nh\xE2n \u0111\xFAng c\xF3 \u0111\u1EE7 \u0111\u1EC3 \xE1p d\u1EE5ng kh\xF4ng?", reasoning: ["\u0110\u1ED1i t\u01B0\u1EE3ng c\u1EE7a kho\u1EA3ng tham chi\u1EBFu kh\xE1c ho\xE0n c\u1EA3nh \u0111i\u1EC1u tr\u1ECB.", "C\u1EA7n h\u01B0\u1EDBng d\u1EABn dinh d\u01B0\u1EE1ng ri\xEAng v\xE0 th\xF4ng tin b\u1EC7nh.", "Coach kh\xF4ng s\u1EEDa ch\u1EC9 \u0111\u1ECBnh b\u1EB1ng m\u1ED9t c\xF4ng th\u1EE9c h\u1ECDc t\u1EADp."], safeNextStep: "Gi\u1EEF h\u01B0\u1EDBng d\u1EABn hi\u1EC7n c\xF3 v\xE0 h\u1ECFi ng\u01B0\u1EDDi ph\u1EE5 tr\xE1ch; d\xF9ng ca gi\u1EA3 \u0111\u1ECBnh \u0111\u1EC3 ho\xE0n th\xE0nh ph\xE9p t\xEDnh.", commonError: "Coi c\xE2n n\u1EB7ng gi\u1ED1ng nhau \u0111\u1ED3ng ngh\u0129a m\u1ECDi nhu c\u1EA7u v\xE0 gi\u1EDBi h\u1EA1n \u0111\u1EC1u gi\u1ED1ng nhau." },
    { id: "ch14-case-appetite", title: "Ch\xE1n \u0103n v\xE0 s\u1EE5t c\xE2n kh\xF4ng ch\u1EE7 \xFD", context: "Nh\xE2n v\u1EADt \u0103n kh\xF3 h\u01A1n k\xE9o d\xE0i, \u0111ang s\u1EE5t c\xE2n v\xE0 \u0111\u01B0\u1EE3c khuy\xEAn c\u1EE9 th\xEAm mass gainer.", question: "V\xEC sao c\u1EA7n b\u01B0\u1EDBc kh\xE1c tr\u01B0\u1EDBc ch\u1ECDn s\u1EA3n ph\u1EA9m?", reasoning: ["\u0110\xE2y kh\xF4ng ch\u1EC9 l\xE0 c\xE2u h\u1ECFi m\u1EADt \u0111\u1ED9 n\u0103ng l\u01B0\u1EE3ng.", "Tri\u1EC7u ch\u1EE9ng v\xE0 s\u1EE5t c\xE2n kh\xF4ng ch\u1EE7 \xFD c\u1EA7n \u0111\xE1nh gi\xE1.", "Kh\xF4ng n\xEAn \u0111\u1EC3 l\u1EDDi khuy\xEAn c\u1ED1 \u0103n che v\u1EA5n \u0111\u1EC1 ch\u01B0a r\xF5."], safeNextStep: "T\xECm \u0111\xE1nh gi\xE1 y t\u1EBF ph\xF9 h\u1EE3p s\u1EDBm; n\u1EBFu c\xF3 bi\u1EC3u hi\u1EC7n c\u1EA5p n\u1EB7ng th\xEC \u01B0u ti\xEAn tr\u1EE3 gi\xFAp kh\u1EA9n c\u1EA5p.", commonError: "Coi m\u1ECDi kh\xF3 t\u0103ng c\xE2n l\xE0 thi\u1EBFu quy\u1EBFt t\xE2m ho\u1EB7c thi\u1EBFu m\u1ED9t lo\u1EA1i b\u1ED9t." }
