  cases: [
    { id: "ch20-case-certificate", title: "H\u1ECDc xong n\xEAn mu\u1ED1n t\u1EF1 k\xEA cho ng\u01B0\u1EDDi kh\xE1c", context: "Ng\u01B0\u1EDDi h\u1ECDc \u0111\u1EA1t c\xE1c b\xE0i v\xE0 mu\u1ED1n d\xF9ng k\u1EBFt qu\u1EA3 l\xE0m b\u1EB1ng ch\u1EE9ng \u0111\u1EE7 chuy\xEAn m\xF4n k\xEA \u0103n cho ng\u01B0\u1EDDi c\xF3 b\u1EC7nh.", question: "K\u1EBFt qu\u1EA3 kh\xF3a cho ph\xE9p k\u1EBFt lu\u1EADn g\xEC?", reasoning: ["B\xE0i ch\u1EA5m l\u1EADp lu\u1EADn theo ph\u1EA1m vi h\u1ECDc t\u1EADp.", "Ki\u1EBFn th\u1EE9c kh\xF3a kh\xF4ng thay \u0111\xE0o t\u1EA1o v\xE0 th\u1EA9m quy\u1EC1n chuy\xEAn m\xF4n.", "H\u1ED3 s\u01A1 b\u1EC7nh c\u1EA7n ng\u01B0\u1EDDi ph\xF9 h\u1EE3p v\xE0 d\u1EEF ki\u1EC7n th\u1EF1c t\u1EBF."], safeNextStep: "Gi\u1EEF vai tr\xF2 h\u1ED7 tr\u1EE3 trong ph\u1EA1m vi, t\xECm ng\u01B0\u1EDDi c\xF3 chuy\xEAn m\xF4n ph\xF9 h\u1EE3p; kh\xF4ng gi\u1EDBi thi\u1EC7u \u0111i\u1EC3m kh\xF3a nh\u01B0 gi\u1EA5y ph\xE9p \u0111i\u1EC1u tr\u1ECB.", commonError: "\u0110\u1ED5i nh\xE3n ho\xE0n th\xE0nh ho\u1EB7c nh\u1EADn x\xE9t coach th\xE0nh ch\u1EE9ng nh\u1EADn h\xE0nh ngh\u1EC1." },
    { id: "ch20-case-treatment", title: "T\u1EF1 ch\u1EE7 n\xEAn t\u1EF1 ng\u1EEBng thu\u1ED1c", context: "M\u1ED9t h\u1ECDc vi\xEAn th\u1EA5y b\u1EEFa \u0103n t\u1ED1t h\u01A1n v\xE0 mu\u1ED1n ng\u1EEBng thu\u1ED1c \u0111\u1EC3 th\u1EED xem c\u01A1 th\u1EC3 \u0111\xE3 t\u1EF1 c\xE2n b\u1EB1ng ch\u01B0a.", question: "Khung 6\u0110 c\xF3 cho ph\xE9p th\u1EED \u0111i\u1EC1u tr\u1ECB nh\u01B0 v\u1EADy kh\xF4ng?", reasoning: ["Nh\u1EADt k\xFD b\u1EEFa kh\xF4ng ch\u1EE9ng minh h\u1EBFt nhu c\u1EA7u \u0111i\u1EC1u tr\u1ECB.", "Thay thu\u1ED1c c\xF3 r\u1EE7i ro ngo\xE0i ph\u1EA1m vi b\xE0i.", "C\xF3 th\u1EC3 ghi c\xE2u h\u1ECFi \u0111\u1EC3 trao \u0111\u1ED5i ng\u01B0\u1EDDi k\xEA thu\u1ED1c."], safeNextStep: "Kh\xF4ng t\u1EF1 thay ho\u1EB7c ng\u1EEBng thu\u1ED1c; trao \u0111\u1ED5i v\u1EDBi ng\u01B0\u1EDDi k\xEA v\xE0 gi\u1EEF h\u01B0\u1EDBng d\u1EABn \u0111ang c\xF3 trong l\xFAc l\xE0m r\xF5.", commonError: "G\u1ECDi vi\u1EC7c t\u1EF1 ng\u1EEBng thu\u1ED1c l\xE0 th\u1EED nghi\u1EC7m c\xE1 nh\xE2n c\xF3 tr\xE1ch nhi\u1EC7m v\xEC \u0111\xE3 ghi d\u1EEF li\u1EC7u." },
    { id: "ch20-case-privacy", title: "Mu\u1ED1n d\u1EEBng chia s\u1EBB sau kh\xF3a", context: "Ng\u01B0\u1EDDi h\u1ECDc mu\u1ED1n t\u1EF1 ti\u1EBFp t\u1EE5c k\u1EBF ho\u1EA1ch v\xE0 kh\xF4ng chia s\u1EBB th\xEAm nh\u1EADt k\xFD sinh ho\u1EA1t v\u1EDBi coach.", question: "\u0110i\u1EC1u g\xEC c\u1EA7n b\xE0n giao?", reasoning: ["T\u1EF1 ch\u1EE7 g\u1ED3m quy\u1EC1n ki\u1EC3m so\xE1t d\u1EEF li\u1EC7u v\xE0 ch\u1ECDn h\u1ED7 tr\u1EE3.", "C\xF3 th\u1EC3 gi\u1EEF ri\xEAng k\u1EBF ho\u1EA1ch, c\xE2u h\u1ECFi v\xE0 \u0111\u01B0\u1EDDng li\xEAn h\u1EC7 khi c\u1EA7n.", "Kh\xF4ng d\xF9ng vi\u1EC7c ti\u1EBFp t\u1EE5c chia s\u1EBB l\xE0m \u0111i\u1EC1u ki\u1EC7n c\xF4ng nh\u1EADn b\xE0i \u0111\xE3 h\u1ECDc."], safeNextStep: "Th\u1ED1ng nh\u1EA5t ph\u1EA1m vi chia s\u1EBB mong mu\u1ED1n v\xE0 \u0111\u01B0\u1EDDng t\xECm l\u1EA1i h\u1ED7 tr\u1EE3; kh\xF4ng h\u1EE9a \u0111\xE3 x\xF3a l\u1ECBch s\u1EED ho\u1EB7c thu h\u1ED3i m\u1ECDi b\u1EA3n sao n\u1EBFu ch\u01B0a x\xE1c minh.", commonError: "\xC9p chia s\u1EBB v\xF4 h\u1EA1n ho\u1EB7c h\u1EE9a x\xF3a to\xE0n b\u1ED9 d\u1EEF li\u1EC7u ch\u1EC9 b\u1EB1ng l\u1EDDi n\xF3i." }
  ],
